  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_supply",
        "name": "Power supply",
        "description": "Power supply assembly from which the cover and component barrier are removed and installed.",
        "category": "power"
      },
      {
        "component_id": "comp_power_supply_cover",
        "name": "Power supply cover",
        "description": "Removable cover fitted onto the power supply; its louvers are positioned in front of the fan.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_front_panel",
        "name": "Front panel",
        "description": "Panel aligned with the power supply and used to retain the cover and component barrier.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_rear_panel",
        "name": "Rear panel",
        "description": "Panel aligned with the power supply and used to retain the cover and component barrier.",
        "category": "enclosure"
      },
      {
        "component_id": "comp_handle",
        "name": "Handle",
        "description": "Handle attached with two screws over the top of the power supply cover.",
        "category": "structural"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "Fan located behind the largest louvers in the power supply cover.",
        "category": "cooling"
      },
      {
        "component_id": "comp_component_barrier",
        "name": "Component barrier",
        "description": "Flexible barrier fitted on the power board side of the power supply, with its folded top edge covering the power board.",
        "category": "electrical protection"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board on the power board side of the power supply, covered at the top by the component barrier.",
        "category": "electrical"
      },
      {
        "component_id": "comp_ground_clip",
        "name": "Ground clip",
        "description": "Clip whose hole is aligned with the screw holes in the rear panel and power supply when installing the cover.",
        "category": "electrical grounding"
      },
      {
        "component_id": "comp_plastic_base",
        "name": "Plastic base",
        "description": "Base with inside notches that retain the bottom edge of the component barrier.",
        "category": "structural"
      }
    ],
